typedef unsigned char uint8;
extern "C" float sqrtf(float);
extern "C" double fabs(double);

inline float fast_recip_sqrt(float x) { return 1.0F / sqrtf(x); }

class vector3d {
public:
  typedef float T;
  T x, y, z;
  inline vector3d() {}
  inline vector3d(const vector3d& v) { x = v.x; y = v.y; z = v.z; }
  inline vector3d(T _x, T _y, T _z) { x = _x; y = _y; z = _z; }
  inline vector3d& operator-=(const vector3d& v) { x -= v.x; y -= v.y; z -= v.z; return *this; }
  inline vector3d& operator*=(T d) { x *= d; y *= d; z *= d; return *this; }
  inline T length2() const { return x*x + y*y + z*z; }
  inline vector3d& normalize() { T l2 = length2(); if (l2 > 0.00001f*0.00001f) *this *= fast_recip_sqrt(l2); return *this; }
  inline vector3d operator-() const { return vector3d(-x, -y, -z); }
};
inline vector3d operator*(vector3d::T d, const vector3d& a) { return vector3d(d*a.x, d*a.y, d*a.z); }
inline vector3d::T dot(const vector3d& a, const vector3d& b) { vector3d::T t = a.x*b.x + a.y*b.y + a.z*b.z; return t; }

extern vector3d XVEC;
extern vector3d YVEC;
extern vector3d ZVEC;

enum {
  GRAB_TURN = 2,
  WAVE_REGIONFACE = 3,
  WAVE_REGIONLIP = 5,
  WAVE_REGIONPOCKET = 6,
  WAVE_REGIONCHIN = 11,
  WAVE_REGIONLIP2 = 12,
  TRICK_ROUNDHOUSECARVE = 88,
  TRICK_TOPCARVE = 89,
  TRICK_BOTTOMCARVE = 90,
  TRICK_TOPGRAB = 92,
  TRICK_BOTTOMGRAB = 93,
  TRICK_GRABROUNDHOUSE = 94
};

class ScoringManager {
public:
  enum ATTRIBUTE { ATTR_DIST_LIP };
  void AddTrick(int) __asm__("AddTrick__14ScoringManageri");
  void UpdateLastTrick(ATTRIBUTE, float, int = 0) __asm__("UpdateLastTrick__14ScoringManagerQ214ScoringManager9ATTRIBUTEfi");
};

class kellyslater_controller {
  char pad[4344];
  ScoringManager my_scoreManager;
public:
  ScoringManager& get_my_scoreManager() { return my_scoreManager; }
  float Tube_Distance() __asm__("Tube_Distance__22kellyslater_controller");
};

#define assert(x) ((void)0)
#define MAX_CARVE_FRAMES 20
class CarveManager {
  struct CarveNode { float time; float angle; vector3d board_vec; vector3d position; uint8 state; int region; };
  float board_angle;
  vector3d cur_board_vec;
  vector3d last_board_vec;
  int TurnType;
  int Head;
  int Tail;
  float angle;
  float time;
  float last_record_time;
  int hardest_region;
  kellyslater_controller *ksctrl;
public:
  CarveNode CarveArray[MAX_CARVE_FRAMES];
  void DetermineTrick(int start, int end);
};

void CarveManager::DetermineTrick(int start, int end)
{
//	float angle = CarveArray[end].angle - CarveArray[start].angle;
	vector3d vec = CarveArray[start].board_vec;
	vec -= YVEC*dot(YVEC, vec);
	vec.normalize();

    assert(ksctrl);

	if (dot(vec, ZVEC) > 0.707f)
	{
		ksctrl->get_my_scoreManager().AddTrick((TurnType == GRAB_TURN)?TRICK_TOPGRAB:TRICK_TOPCARVE);
	}
	else if (fabs(dot(vec, XVEC)) > 0.707)
	{
		ksctrl->get_my_scoreManager().AddTrick((TurnType == GRAB_TURN)?TRICK_GRABROUNDHOUSE:TRICK_ROUNDHOUSECARVE);
	}
	else if (dot(vec, -ZVEC) > 0.707f)
	{
		ksctrl->get_my_scoreManager().AddTrick((TurnType == GRAB_TURN)?TRICK_BOTTOMGRAB:TRICK_BOTTOMCARVE);
	}

	float	vert_mod;
	if ((hardest_region == WAVE_REGIONLIP) || (hardest_region == WAVE_REGIONLIP2) || (hardest_region == WAVE_REGIONCHIN))
		vert_mod = 1.0f;
	else if (hardest_region == WAVE_REGIONFACE)
		vert_mod = 0.5f;
	else if (hardest_region == WAVE_REGIONPOCKET)
		vert_mod = 0.0f;
	else
		{ assert(0); return; }

	ksctrl->get_my_scoreManager().UpdateLastTrick(ScoringManager::ATTR_DIST_LIP, vert_mod);

	float scale;
	float tube_dist = ksctrl->Tube_Distance();
	if (tube_dist < -0.2f)
		scale = 1.0f;
	else
		scale = 0.8f - tube_dist;

	if (scale < 0.0f)
		scale = 0.0f;
	else if (scale > 1.0f)
		scale = 1.0f;
}
